fn gate() -> Arc<SameActorPhaseGate> {
    SameActorPhaseGate::from_original_deadline(
        SameActorPhaseDeadline::at_original_service_start(Duration::from_secs(10)).unwrap(),
    ).unwrap()
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn unpolled_receive_keeps_real_task_and_fd_until_cleanup_join() {
    let gate = gate();
    let registry = Arc::new(OriginalBootstrapConsumers::new());
    let (owner, mut peer) = UnixStream::pair().unwrap();
    peer.set_nonblocking(true).unwrap();
    let (entered, started) = mpsc::sync_channel(1);
    let (release, released) = mpsc::sync_channel(1);
    let admission = registry.reserve(OriginalBootstrapConsumerKind::Device, &gate).unwrap();
    let worker = tokio::task::spawn_blocking(move || {
        let _owner = owner;
        entered.send(()).unwrap();
        let _ = released.recv();
        Err(AgentdError::GenerationFenced("actual component consumer refused".into()))
    });
    let job = admission.retain_original_handle(worker);
    started.recv_timeout(Duration::from_secs(2)).unwrap();
    drop(job.receive_original());
    assert!(gate.require_open().is_err());
    let mut byte = [0];
    assert!(matches!(peer.read(&mut byte), Err(error) if error.kind() == std::io::ErrorKind::WouldBlock));
    let actual = Arc::clone(&registry);
    let mut cleanup = tokio::spawn(async move { actual.join_and_release().await });
    assert!(tokio::time::timeout(Duration::from_millis(20), &mut cleanup).await.is_err());
    release.send(()).unwrap();
    let result = cleanup.await.unwrap();
    assert!(matches!(result, Err(AgentdError::GenerationFenced(message))
        if message == "actual component consumer refused"));
    assert!(matches!(peer.read(&mut byte), Ok(0)));
    let state = job.state.lock().await;
    assert!(state.joined && state.handle.is_none() && state.output.is_none());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn one_actual_consumer_kind_cannot_be_spawned_twice() {
    let gate = gate();
    let registry = OriginalBootstrapConsumers::new();
    let admission = registry.reserve(OriginalBootstrapConsumerKind::Device, &gate).unwrap();
    let worker = tokio::task::spawn_blocking(|| {
        Err(AgentdError::GenerationFenced("first actual refusal".into()))
    });
    let job = admission.retain_original_handle(worker);
    assert!(registry.reserve(OriginalBootstrapConsumerKind::Device, &gate).is_err());
    assert!(registry.reserve(OriginalBootstrapConsumerKind::Notes, &gate).is_err());
    assert!(registry.join_and_release().await.is_err());
    let state = job.state.lock().await;
    assert!(state.joined && state.handle.is_none());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn panicked_consumer_does_not_skip_the_other_actual_join() {
    let gate = gate();
    let registry = Arc::new(OriginalBootstrapConsumers::new());
    let first = registry.reserve(OriginalBootstrapConsumerKind::Device, &gate).unwrap()
        .retain_original_handle(tokio::task::spawn_blocking(|| -> Result<FinalUseAuthority, AgentdError> {
            panic!("actual component consumer panic");
        }));
    let (owner, mut peer) = UnixStream::pair().unwrap();
    peer.set_nonblocking(true).unwrap();
    let (release, released) = mpsc::sync_channel(1);
    let second = registry.reserve(OriginalBootstrapConsumerKind::Notes, &gate).unwrap()
        .retain_original_handle(tokio::task::spawn_blocking(move || {
            let _owner = owner;
            let _ = released.recv();
            Err(AgentdError::GenerationFenced("second actual refusal".into()))
        }));
    let actual = Arc::clone(&registry);
    let mut cleanup = tokio::spawn(async move { actual.join_and_release().await });
    assert!(tokio::time::timeout(Duration::from_millis(20), &mut cleanup).await.is_err());
    let mut byte = [0];
    assert!(matches!(peer.read(&mut byte), Err(error) if error.kind() == std::io::ErrorKind::WouldBlock));
    release.send(()).unwrap();
    assert!(matches!(cleanup.await.unwrap(), Err(AgentdError::Protocol(_))));
    assert!(matches!(peer.read(&mut byte), Ok(0)));
    assert!(first.state.lock().await.joined);
    assert!(second.state.lock().await.joined);
}

//! Actual selected Startup driver, owned by a retained std thread.
//! The receiver is driven through its original awaits. Its two bootstrap
//! blocking handles and Session tasks are also retained by that outer owner.

use super::*;

pub(super) async fn run_owned_original_phase(
    startup: AgentdOriginalSameActorPhaseStartupV1,
    selected: owner::OriginalPhaseSelectedBusiness,
    arg0_paths: Arg0DispatchPaths,
    control: Arc<owner::OriginalPhaseRunControl>,
) -> Result<(), AgentdError> {
    let AgentdOriginalSameActorPhaseStartupV1 {
        identity,
        cognitive_mode,
        inputs,
        mut receiver,
        phase_handoff,
        scoped_handoff,
    } = startup;
    let LaunchInputs {
        handoff,
        learning_handoff: _,
        q24_model_handoff: _,
        publication_handoff: _,
        initial_handoff: _,
        uid,
        gid,
        control: control_socket,
        app_server,
        primary,
        bootstrap_deadline: _,
        notes,
        notes_ui,
        lifetime: _,
    } = inputs;
    late_writer::require_late_owner(uid, gid)?;
    let (bootstrap, root_pidfd, writer) = tokio::task::block_in_place(|| {
        let timeout = receiver.remaining()?.min(Duration::from_millis(500));
        let original = crate::receive_root_production_writer_handoff(handoff, timeout)?;
        receiver.remaining()?;
        Ok::<_, AgentdError>(original)
    })?;
    let phase = tokio::task::block_in_place(|| {
        let timeout = receiver.remaining()?.min(Duration::from_millis(500));
        let phase = receive_original_phase_start(phase_handoff, timeout, receiver.instant())?;
        receiver.remaining()?;
        Ok::<_, AgentdError>(phase)
    })?;
    let timeout = receiver.remaining()?.min(Duration::from_millis(500));
    let OriginalSameActorProductionInputs {
        mut root,
        context,
        initial,
    } = receive_original_same_actor_inputs(
        bootstrap, root_pidfd, phase, &identity, timeout, receiver, control.as_ref(),
    )
    .await?;
    // From this point onward the actual same-Gate close guard already
    // exists outside every later future, including never-polled work.
    let _closing = CloseSameActorPhaseOnDrop::new(context.gate());
    control.retain_original_context(&context)?;
    let config =
        AgentdConfig::from_root_writer_handoff(&root, writer, std::env::current_dir()?)?
            .with_root_bound_sockets(control_socket, app_server)?
            .with_cognitive_retrieval_mode(cognitive_mode);
    if config.identity() != &identity || context.identity() != &identity {
        return Err(refused(
            "original Starting Config differs from the received phase",
        ));
    }
    let (mut business, mut coordinator) = match selected {
        owner::OriginalPhaseSelectedBusiness::Embedded(business) => (*business, None),
        owner::OriginalPhaseSelectedBusiness::Deployment(descriptor) => {
            let (business, coordinator) = crate::same_actor_q24_deployment::open_original_deployment(
                Arc::clone(&context), descriptor,
            ).await?;
            (business, Some(coordinator))
        }
    };
    OriginalSameActorRootContext::require_current(&context)?;
    business.host.notify_original(
        &context,
        OriginalSameActorPhaseEventV1::InputsOpened {
            identity: Box::new(identity.clone()),
            phase: context.descriptor().phase.clone(),
        },
    )?;
    if !matches!(
        business.host.receive_original(&context).await?,
        OriginalSameActorPhaseCommandV1::InitialRootEnrolled
    ) {
        return Err(refused(
            "actual Initial Root enrollment must precede connection",
        ));
    }
    let connection =
        crate::AgentdRootProductionInputs::take_generation_publication_connection(&mut root)?;
    let initial = initial
        .connect_original_same_actor_initial(
            connection,
            Arc::clone(&context),
            Duration::from_millis(500),
        )
        .await?;
    OriginalSameActorRootContext::require_current(&context)?;
    // Original synchronous owners complete before this poll returns.
    // block_in_place lets the original refresh worker continue; it
    // creates no detached owner task or discardable JoinHandle.
    let (config, circuit) = tokio::task::block_in_place(|| {
        install_original_initial_task(
            config,
            Arc::clone(&context),
            initial,
            business,
            scoped_handoff,
        )
    })?;
    control.retain_original_circuit(&context, circuit)?;
    late_writer::require_late_owner(uid, gid)?;
    OriginalSameActorRootContext::require_current(&context)?;
    let launch = AgentdProductionLaunch {
        root,
        inputs: RuntimeInputs {
            primary,
            notes,
            notes_ui,
        },
        q24_model: None,
        publication: None,
        initial_publication: None,
    };
    // Retain the same actual attachment through original Runtime return.
    // This version has fault cleanup only; a successful generic return
    // cannot release the final Err or mint normal-retirement permission.
    let result = match launch.run_original_same_actor_with_shutdown(
        config, arg0_paths, Arc::clone(&context), Arc::clone(&control),
    ).await {
        Ok(stopped) => {
            stopped.close_original_runtime_resources().await;
            Err(refused("original phase completion and physical owner join are not acknowledged"))
        }
        Err(error) => Err(error),
    };
    if let Some(coordinator) = coordinator.as_mut() {
        if let Err(error) = coordinator.stop_and_join_original() {
            if result.is_ok() { return Err(error); }
            tracing::error!(error = %error, "original deployment coordinator also failed");
        }
    }
    result
}

//! Exact original Android launch with an explicit phase shutdown owner.
//! The legacy Launch.run body is unchanged. Successful Runtime return only
//! creates custody of the actual still-live attachment; it is not a join or
//! a business-completion certificate.

use super::*;
use crate::root_production_inputs::same_actor_phase::OriginalSameActorRootContext;
use crate::same_actor_q24_phase_gate::{CloseSameActorPhaseOnDrop, SameActorPhaseGate};

/// No public constructor, Clone or wire representation. Only the actual
/// run_with_shutdown Ok branch below constructs this owner. Keeping this
/// value retains the original Session/checkpoint/grants and Primary runtime.
pub(crate) struct OriginalSameActorRuntimeStopped {
    context: Arc<OriginalSameActorRootContext>,
    root_pidfd: OwnedFd,
    attachment: Option<crate::AgentdRootProductionAttachment>,
    device: Option<Arc<crate::AgentdAndroidTextDevice>>,
    mcp: Option<codex_app_server::ConfiguredMcpRuntime>,
    closing: CloseSameActorPhaseOnDrop,
}

impl OriginalSameActorRuntimeStopped {
    pub(crate) fn require_original_origin(
        &self, identity: &AgentdIdentity, gate: &Arc<SameActorPhaseGate>,
    ) -> Result<(), AgentdError> {
        if self.context.identity() != identity || !Arc::ptr_eq(self.context.gate(), gate)
            || self.attachment.is_none() || self.device.is_none() || self.mcp.is_none()
        {
            self.context.gate().close();
            return Err(runtime_refused("actual stopped Runtime custody differs"));
        }
        self.context.gate().require_open()?;
        crate::root_observation_stream::check_lifetime(&self.root_pidfd)
            .map_err(|error| AgentdError::Protocol(format!("original stopped Root lifetime: {error}")))
    }

    /// Fault cleanup only. No Root retirement permission or natural Session
    /// completion is inferred from this operation.
    pub(super) async fn close_original_runtime_resources(mut self) {
        self.context.gate().close();
        drop(self.attachment.take());
        if let Some(device) = self.device.take() { device.invalidate(); }
        if let Some(mcp) = self.mcp.take() { mcp.shutdown().await; }
        // Keep the shared close responsibility armed, including cancellation.
        let _ = &self.closing;
    }
}

impl Drop for OriginalSameActorRuntimeStopped {
    fn drop(&mut self) {
        self.context.gate().close();
        if let Some(device) = &self.device { device.invalidate(); }
        // Synchronous Drop requests failure and retains no false join claim.
        // The actual outer owner normally drives the explicit async cleanup.
    }
}

impl AgentdProductionLaunch {
    pub(super) async fn run_original_same_actor_with_shutdown(
        self,
        mut config: AgentdConfig,
        arg0_paths: Arg0DispatchPaths,
        context: Arc<OriginalSameActorRootContext>,
        stop: Arc<same_actor_phase::owner::OriginalPhaseRunControl>,
    ) -> Result<OriginalSameActorRuntimeStopped, AgentdError> {
        let mut closing = CloseSameActorPhaseOnDrop::new(context.gate());
        let identity = context.identity().clone();
        let gate = Arc::clone(context.gate());
        OriginalSameActorRootContext::require_current(&context)?;
        let root_pidfd = context.root_pidfd()?;
        config.require_root_learning_assembled()?;
        if config.identity() != context.identity() || self.initial_publication.is_some()
            || self.publication.is_some() || self.q24_model.is_some()
        {
            return Err(runtime_refused(
                "actual phase Runtime has unresolved original handoffs or identity",
            ));
        }
        let RuntimeInputs { primary, notes, notes_ui } = self.inputs;
        if notes_ui.is_some() {
            return Err(runtime_refused("phase Circuit profile forbids Notes UI"));
        }
        let PrimaryInputs::Android { server, environment, payload, deadline } = primary else {
            return Err(runtime_refused("phase requires the actual Android Primary"));
        };
        let mut mcp: Option<codex_app_server::ConfiguredMcpRuntime> = None;
        let mut device: Option<Arc<crate::AgentdAndroidTextDevice>> = None;
        let mut attachment: Option<crate::AgentdRootProductionAttachment> = None;
        let result = async {
            let payload_json = inputs::read_payload(payload)?;
            let home = AbsolutePathBuf::from_absolute_path(&config.identity().home_root)
                .map_err(|error| AgentdError::Invalid(error.to_string()))?;
            let workspace = AbsolutePathBuf::from_absolute_path(&config.identity().workspace)
                .map_err(|error| AgentdError::Invalid(error.to_string()))?;
            let original = codex_app_server::initialize_configured_mcp_server(
                home, workspace, arg0_paths.clone(), &server, &environment, remaining(deadline)?,
            ).await.map_err(|error| {
                AgentdError::Protocol(format!("original Runtime MCP startup: {error}"))
            })?;
            mcp = Some(original);
            let original = mcp.as_ref().ok_or_else(|| {
                AgentdError::Protocol("original MCP startup handle disappeared".into())
            })?;
            let android = AgentdAndroidRuntimeInputs::from_mcp_binding(
                original.binding(), &server, &environment, tokio::runtime::Handle::current(),
                payload_json, deadline,
            ).await?;
            let (target, actual_device) = crate::prepare_android_runtime_target(android)?;
            device = Some(actual_device);
            let target: Arc<dyn FinalUseProductionOutboxTarget> = target;
            attachment = Some(crate::attach_root_production_operation_host_with_startup(
                &mut config, self.root, target, notes, Duration::from_millis(100), None,
            ).await?);
            remaining(deadline)?;
            OriginalSameActorRootContext::require_current(&context)?;
            // This exact original Runtime still owns ordinary readiness,
            // signed ingress, reconciliation and all original shutdown rules.
            crate::run_with_shutdown(config, arg0_paths, stop.wait_original_shutdown()).await?;
            context.gate().require_open()?;
            crate::root_observation_stream::check_lifetime(&root_pidfd)
                .map_err(|error| AgentdError::Protocol(format!("original stopped Root lifetime: {error}")))?;
            Ok::<(), AgentdError>(())
        }.await;
        if let Err(error) = result {
            context.gate().close();
            drop(attachment.take());
            if let Some(device) = device.take() { device.invalidate(); }
            if let Some(mcp) = mcp.take() { mcp.shutdown().await; }
            return Err(error);
        }
        let stopped = OriginalSameActorRuntimeStopped {
            context, root_pidfd, attachment, device, mcp,
            closing: CloseSameActorPhaseOnDrop::new(&gate),
        };
        stopped.require_original_origin(&identity, &gate)?;
        closing.disarm();
        Ok(stopped)
    }
}

fn runtime_refused(message: &str) -> AgentdError {
    AgentdError::GenerationFenced(message.into())
}

//! Explicit ordinary daemon selector for real deployment-owned phase material.
//! No descriptor is opened before the original inherited-rights parser has
//! taken its disjoint FDs. Missing mode leaves the legacy selector unchanged.

use std::os::fd::{FromRawFd, OwnedFd};
use std::path::PathBuf;
use codex_hepta_types::Digest32;
use super::*;
use crate::same_actor_q24_deployment::OriginalDeploymentDescriptor;

pub struct AgentdOriginalSameActorDeploymentStartupV1 {
    startup: AgentdOriginalSameActorPhaseStartupV1,
    descriptor: OriginalDeploymentDescriptor,
}

impl AgentdOriginalSameActorDeploymentStartupV1 {
    pub fn select_from_process_environment(
        arguments: Vec<OsString>,
    ) -> Result<(Option<Self>, Vec<OsString>), AgentdError> {
        // The default branch performs no clock, file or inherited-FD action.
        if !arguments.iter().any(|flag| flag == "--original-same-actor-deployment") {
            return Ok((None, arguments));
        }
        Self::prepare_selected_original(arguments).map(|startup| (Some(startup), Vec::new()))
    }

    fn prepare_selected_original(arguments: Vec<OsString>) -> Result<Self, AgentdError> {
        // First selected-mode statement, before even parsing our flags or
        // taking descriptors. The original parser may only shorten this end.
        let start = OriginalPhaseReceiveStart::capture()?;
        let mut descriptor = None;
        let mut digest = None;
        let mut phase = None;
        let mut scoped = None;
        let mut forwarded = Vec::new();
        let mut args = arguments.into_iter();
        while let Some(flag) = args.next() {
            let value = args.next().ok_or_else(|| refused("original phase flag requires a value"))?;
            if flag == "--original-same-actor-deployment" {
                if descriptor.replace(PathBuf::from(value)).is_some() {
                    return Err(refused("duplicate original deployment descriptor"));
                }
            } else if flag == "--original-same-actor-deployment-digest" {
                if digest.is_some() { return Err(refused("duplicate original deployment digest")); }
                digest = Some(value.to_str().ok_or_else(|| refused("deployment digest requires UTF-8"))?
                    .parse::<Digest32>().map_err(|error| AgentdError::Invalid(error.to_string()))?);
            } else if flag == "--root-same-actor-phase-handoff-fd" {
                if phase.replace(original_descriptor_number(&value)?).is_some() {
                    return Err(refused("duplicate original phase handoff"));
                }
            } else if flag == "--root-same-actor-scoped-handoff-fd" {
                if scoped.replace(original_descriptor_number(&value)?).is_some() {
                    return Err(refused("duplicate original scoped handoff"));
                }
            } else {
                forwarded.push(flag);
                forwarded.push(value);
            }
        }
        let phase = phase.ok_or_else(|| refused("actual original phase handoff FD required"))?;
        let scoped = scoped.ok_or_else(|| refused("actual original scoped handoff FD required"))?;
        let descriptor = OriginalDeploymentDescriptor::from_original_arguments(
            descriptor.ok_or_else(|| refused("actual deployment descriptor required"))?,
            digest.ok_or_else(|| refused("exact original deployment digest required"))?,
        )?;
        // All raw aliases are rejected BEFORE either FD becomes an OwnedFd,
        // including aliases of all fifteen original parser-owned rights.
        require_disjoint_phase_descriptor_numbers(&forwarded, [phase, scoped])?;
        let phase = take_original_datagram(phase)?;
        let scoped = take_original_datagram(scoped)?;
        let (startup, ordinary) = AgentdOriginalSameActorPhaseStartupV1::from_original_receive_start(
            forwarded, phase, scoped, start,
        )?;
        if !ordinary.is_empty() {
            return Err(refused("explicit phase material must come from its pinned deployment descriptor"));
        }
        Ok(Self { startup, descriptor })
    }

    pub fn identity(&self) -> &AgentdIdentity { self.startup.identity() }

    pub async fn run_original_deployment(
        self, arg0_paths: Arg0DispatchPaths,
    ) -> Result<(), AgentdError> {
        owner::OriginalPhaseRunOwner::start_original(
            self.startup,
            owner::OriginalPhaseSelectedBusiness::Deployment(self.descriptor),
            arg0_paths,
        )?.await
    }
}

fn original_descriptor_number(value: &OsString) -> Result<i32, AgentdError> {
    value.to_str().and_then(|value| value.parse::<i32>().ok()).filter(|fd| *fd >= 3)
        .ok_or_else(|| refused("original inherited descriptor must be an integer above stderr"))
}

fn take_original_datagram(number: i32) -> Result<UnixDatagram, AgentdError> {
    // SAFETY: this only inspects and tightens the disjoint inherited FD. No
    // descriptor is allocated between raw alias checks and ownership taking.
    let flags = unsafe { libc::fcntl(number, libc::F_GETFD) };
    if flags < 0 { return Err(std::io::Error::last_os_error().into()); }
    // SAFETY: CLOEXEC only narrows inheritance of this still-live exact FD.
    if unsafe { libc::fcntl(number, libc::F_SETFD, flags | libc::FD_CLOEXEC) } != 0 {
        return Err(std::io::Error::last_os_error().into());
    }
    // SAFETY: one validated, nonstandard, disjoint transferred right. Actual
    // Root handoff reception still verifies the socket and its Root creator.
    Ok(UnixDatagram::from(unsafe { OwnedFd::from_raw_fd(number) }))
}
